using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;

public record DesignTemplateWrite(string Name,string Kind,string Category,string Design,Guid? UnitId=null,Guid? CategoryId=null,string Designation="",int Revision=0);
public record TemplatePreview(Guid MembershipId,Guid TemplateVersionId,DateOnly ExpiryDate,string Side="Front",string Reason="Preview",Guid? EventId=null,Guid? ProjectId=null);
public static partial class StudioEndpoints {
 public static void Map(RouteGroupBuilder api){var t=api.MapGroup("/societies/{tenant:guid}/studio").RequireAuthorization().RequireRateLimiting("community");t.AddEndpointFilter(async(ctx,next)=>{await ctx.HttpContext.RequestServices.GetRequiredService<Access>().Member(Guid.Parse(ctx.HttpContext.Request.RouteValues["tenant"]!.ToString()!));return await next(ctx);});
  t.MapGet("/setup",async(Guid tenant,AppDb db,Access a,StudioService s)=>new{policy=await s.Policy(tenant),fields=DesignSchema.Fields,organizations=await a.Visible(tenant,"studio.issue").OrderBy(u=>u.Name).Select(u=>new{u.Id,u.Name}).Take(1000).ToListAsync(),designOrganizations=await a.Visible(tenant,"studio.design").OrderBy(u=>u.Name).Select(u=>new{u.Id,u.Name}).Take(1000).ToListAsync(),categories=await db.MembershipCategories.Where(c=>c.TenantId==tenant&&c.Active).Select(c=>new{c.Id,c.Name}).ToListAsync(),myMemberships=await db.Memberships.Where(m=>m.TenantId==tenant&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)).Select(m=>new{m.Id,m.Number,m.ChapterId}).ToListAsync()});
  t.MapPut("/policy",async(Guid tenant,StudioPolicy r,AppDb db,Access a,StudioService s)=>{await a.Require(tenant,"studio.settings");var p=await s.Policy(tenant);if(p.Revision!=r.Revision)return Results.Conflict();p.ChapterCustomization=r.ChapterCustomization;p.MemberDownloads=r.MemberDownloads;p.PublicNames=r.PublicNames;p.Revision++;a.Audit(tenant,"studio.policy.changed",p.Id);await db.SaveChangesAsync();return Results.NoContent();});
  t.MapGet("/templates",async(Guid tenant,string? kind,Guid? workspace,StudioService s,AppDb db,Access a)=>{var q=s.Scoped<DesignTemplate>(tenant,"studio.read",workspace);if(kind!=null)q=q.Where(x=>x.Kind==kind);return await q.OrderByDescending(x=>x.UpdatedAt).Select(x=>new{x.Id,x.Name,x.Kind,x.Category,x.Status,x.UnitId,x.CategoryId,x.Designation,x.Revision,x.PublishedVersion,versions=db.Set<DesignVersion>().Where(v=>v.TemplateId==x.Id&&v.TenantId==tenant).OrderByDescending(v=>v.Version).Select(v=>new{v.Id,v.Version,v.At}).ToList()}).Take(200).ToListAsync();});
  t.MapGet("/templates/{id:guid}",async(Guid tenant,Guid id,AppDb db,StudioService s,Access a)=>{var template=await s.Scoped<DesignTemplate>(tenant).AsNoTracking().SingleOrDefaultAsync(t=>t.Id==id)??throw new AccessDeniedException();if(!await a.Can(tenant,"studio.design",template.UnitId)&&template.PublishedVersion>0){template.Design=await db.Set<DesignVersion>().Where(v=>v.TenantId==tenant&&v.TemplateId==id).OrderByDescending(v=>v.Version).Select(v=>v.Design).FirstAsync();template.Status="Published";}return Results.Ok(new{template,versions=await db.Set<DesignVersion>().Where(v=>v.TenantId==tenant&&v.TemplateId==id).OrderByDescending(v=>v.Version).ToListAsync()});});
  t.MapGet("/starter",(string kind)=>DesignSchema.Starter(kind));
  t.MapGet("/templates/{id:guid}/thumbnail",async(Guid tenant,Guid id,StudioService s,StudioRenderer renderer,Access a,AppDb db)=>{var template=await s.Scoped<DesignTemplate>(tenant).SingleOrDefaultAsync(t=>t.Id==id)??throw new AccessDeniedException();var source=template.Design;if(!await a.Can(tenant,"studio.design",template.UnitId)&&template.PublishedVersion>0)source=await db.Set<DesignVersion>().Where(v=>v.TenantId==tenant&&v.TemplateId==id).OrderByDescending(v=>v.Version).Select(v=>v.Design).FirstAsync();var design=DesignSchema.Parse(source);var fields=DesignSchema.Fields.ToDictionary(k=>k,k=>k=="card.qr_code"?"DRAFT PREVIEW":"["+k+"]");return Results.File(renderer.Image(tenant,new CredentialSnapshot(design,fields,new()),"Front",preview:true,dpi:96),"image/png");});
  t.MapPost("/templates",async(Guid tenant,DesignTemplateWrite r,AppDb db,Access a,StudioService s)=>{await ValidateTemplate(tenant,r,db,a,s);var x=new DesignTemplate{TenantId=tenant,Name=r.Name.Trim(),Kind=r.Kind,Category=r.Category,Design=r.Design,UnitId=r.UnitId,CategoryId=r.CategoryId,Designation=r.Designation,AuthorId=a.UserId};db.Add(x);a.Audit(tenant,"design.created",x.Id);await db.SaveChangesAsync();return Results.Ok(x);});
  t.MapPut("/templates/{id:guid}",async(Guid tenant,Guid id,DesignTemplateWrite r,AppDb db,Access a,StudioService s)=>{await ValidateTemplate(tenant,r,db,a,s);var x=await db.Set<DesignTemplate>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"studio.design",x.UnitId);if(x.Revision!=r.Revision)return Results.Conflict(new{title="Design changed; refresh before saving"});if(x.Kind!=r.Kind||x.UnitId!=r.UnitId)throw new DomainException("Kind and owning organization are fixed; use Save As");x.Name=r.Name.Trim();x.Category=r.Category;x.CategoryId=r.CategoryId;x.Designation=r.Designation;x.Design=r.Design;x.Status="Draft";x.Revision++;x.UpdatedAt=DateTimeOffset.UtcNow;a.Audit(tenant,"design.saved",id);await db.SaveChangesAsync();return Results.Ok(x);});
  t.MapPost("/templates/{id:guid}/publish",async(Guid tenant,Guid id,AppDb db,Access a,StudioService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var x=await db.Set<DesignTemplate>().SingleOrDefaultAsync(x=>x.Id==id&&x.TenantId==tenant)??throw new AccessDeniedException();await a.Require(tenant,"studio.publish",x.UnitId);DesignSchema.Parse(x.Design);if(x.Status=="Published")return Results.Ok(x);x.PublishedVersion++;x.Status="Published";db.Add(new DesignVersion{TenantId=tenant,UnitId=x.UnitId,TemplateId=id,Version=x.PublishedVersion,Design=x.Design,PublisherId=a.UserId});a.Audit(tenant,"design.published",id,new{x.PublishedVersion});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(x);});
  t.MapPost("/templates/{id:guid}/archive",async(Guid tenant,Guid id,AppDb db,Access a)=>{var x=await db.Set<DesignTemplate>().SingleOrDefaultAsync(x=>x.Id==id&&x.TenantId==tenant)??throw new AccessDeniedException();await a.Require(tenant,"studio.publish",x.UnitId);x.Status="Archived";x.Revision++;a.Audit(tenant,"design.archived",id);await db.SaveChangesAsync();return Results.NoContent();});
  t.MapPost("/assets",async(Guid tenant,Guid? unit,HttpRequest request,AppDb db,Access a,IObjectStore store)=>{await a.Require(tenant,"studio.design",unit);if(request.ContentLength is null or >2097152)throw new DomainException("Upload a PNG smaller than 2 MB");using var input=new MemoryStream();await request.Body.CopyToAsync(input);var bytes=AssetEndpoints.SanitizePng(input.ToArray());var asset=new StudioAsset{TenantId=tenant,UnitId=unit,Name=Path.GetFileName(request.Headers["X-Filename"].ToString())[..Math.Min(160,Path.GetFileName(request.Headers["X-Filename"].ToString()).Length)],Length=bytes.Length,AuthorId=a.UserId};await store.Put(tenant,asset.Id,bytes);db.Add(asset);a.Audit(tenant,"studio.asset.uploaded",asset.Id);await db.SaveChangesAsync();return Results.Ok(new{asset.Id,asset.Name,url=$"/api/v1/societies/{tenant}/studio/assets/{asset.Id}"});});
  t.MapGet("/assets",async(Guid tenant,StudioService s)=>await s.Scoped<StudioAsset>(tenant,"studio.design").Where(x=>x.Kind=="Image").OrderByDescending(x=>x.At).Take(100).Select(x=>new{x.Id,x.Name,x.UnitId}).ToListAsync());
  t.MapGet("/assets/{id:guid}",async(Guid tenant,Guid id,StudioService s,IObjectStore store)=>{if(!await s.Scoped<StudioAsset>(tenant,"studio.design").AnyAsync(x=>x.Id==id&&x.Kind=="Image"))throw new AccessDeniedException();return Results.File(store.Open(tenant,id),"image/png");});
  t.MapGet("/members",async(Guid tenant,string? search,StudioService s,AppDb db)=>{var q=s.Select(tenant,new StudioSelection());if(!string.IsNullOrWhiteSpace(search))q=q.Where(m=>EF.Functions.ILike(m.Number,"%"+search+"%")||db.Persons.Any(p=>p.Id==m.PersonId&&EF.Functions.ILike(p.FullName,"%"+search+"%")));return await(from m in q join p in db.Persons on m.PersonId equals p.Id orderby p.FullName select new{m.Id,m.Number,p.FullName,m.ChapterId}).Take(100).ToListAsync();});
  t.MapPost("/selection",async(Guid tenant,StudioSelection r,StudioService s,AppDb db)=>{var q=s.Select(tenant,r);var now=DateTimeOffset.UtcNow;return Results.Ok(new{selected=await q.CountAsync(),expired=await q.CountAsync(m=>m.EndsAt<=now||m.EffectiveFrom>now||m.Status!="Active"),missingPhotos=await q.CountAsync(m=>!db.MemberDocuments.Any(d=>d.TenantId==tenant&&d.MembershipId==m.Id&&d.Kind=="Photo")),missingIdentifiers=await q.CountAsync(m=>m.Number==""),alreadyIssued=await q.CountAsync(m=>db.Set<Credential>().Any(c=>c.TenantId==tenant&&c.MembershipId==m.Id&&c.Kind=="Card"&&c.Status=="Issued"&&c.ExpiryDate>=FinanceService.Today)),items=await (from m in q join p in db.Persons on m.PersonId equals p.Id orderby m.Number select new{m.Id,m.Number,p.FullName,m.ChapterId,m.Status,m.JoinedAt,m.EndsAt}).Take(100).ToListAsync()});});
  t.MapPost("/preview",async(Guid tenant,TemplatePreview r,AppDb db,Access a,StudioService s,StudioRenderer renderer)=>{var m=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==r.MembershipId)??throw new AccessDeniedException();await a.Require(tenant,"studio.issue",m.ChapterId);var v=await s.Version(tenant,r.TemplateVersionId,m.ChapterId);var snapshot=await s.Snapshot(tenant,m,v,FinanceService.Today,r.ExpiryDate,"DRAFT PREVIEW","NOT-AN-ISSUED-CREDENTIAL",r.Reason,r.EventId,r.ProjectId);return Results.File(renderer.Image(tenant,snapshot,r.Side,preview:true),"image/png");});
  t.MapPost("/credentials",async(Guid tenant,CredentialIssue r,AppDb db,StudioService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var card=await s.Request(tenant,r);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(Card(card));});
  t.MapGet("/credentials",async(Guid tenant,string? kind,string? status,int? page,Guid? workspace,bool? mine,AppDb db,StudioService s,Access a)=>{var units=a.InWorkspace(a.Visible(tenant,"studio.read"),tenant,workspace).Select(u=>u.Id);var own=db.Memberships.Where(m=>m.TenantId==tenant&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)).Select(m=>m.Id);var q=db.Set<Credential>().Where(c=>c.TenantId==tenant&&(own.Contains(c.MembershipId)||(c.UnitId!=null&&units.Contains(c.UnitId.Value))));if(mine==true)q=q.Where(c=>own.Contains(c.MembershipId));if(kind!=null)q=q.Where(c=>c.Kind==kind);if(status!=null)q=q.Where(c=>c.Status==status);var rows=await q.OrderByDescending(c=>c.At).Skip(Math.Max(0,(page??1)-1)*50).Take(50).ToListAsync();return Results.Ok(new{total=await q.CountAsync(),items=rows.Select(Card)});});
  t.MapGet("/credentials/{id:guid}",async(Guid tenant,Guid id,StudioService s,AppDb db)=>{var c=await s.Read(tenant,id);return Results.Ok(new{credential=Card(c),snapshot=JsonSerializer.Deserialize<CredentialSnapshot>(c.Snapshot,DesignSchema.Json),history=await db.Set<CommunityDecision>().Where(d=>d.TenantId==tenant&&d.ResourceId==id).OrderBy(d=>d.At).Select(d=>new{d.Decision,d.Note,d.At}).ToListAsync()});});
  t.MapPost("/credentials/{id:guid}/decision",async(Guid tenant,Guid id,StudioReview r,AppDb db,Access a,StudioService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var card=await db.Set<Credential>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id&&c.Status=="Pending Approval")??throw new DomainException("Choose a pending credential");await a.Require(tenant,"studio.approve",card.UnitId);if(card.AuthorId==a.UserId)throw new AccessDeniedException();s.Decision(tenant,id,card.UnitId,"Credential",r);if(r.Decision=="Approve"){var m=await db.Memberships.SingleAsync(m=>m.Id==card.MembershipId&&m.TenantId==tenant);await s.Version(tenant,card.TemplateVersionId,m.ChapterId);if(m.Status!="Active"||m.EndsAt<=DateTimeOffset.UtcNow||m.EffectiveFrom>DateTimeOffset.UtcNow||card.ExpiryDate<FinanceService.Today)throw new DomainException("Member/card is no longer eligible");card.Status="Approved";card.ApproverId=a.UserId;}else{card.Status="Revoked";card.Reason=r.Note;}await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(Card(card));});
  t.MapPost("/credentials/{id:guid}/revoke",async(Guid tenant,Guid id,StudioReview r,AppDb db,Access a,StudioService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var c=await s.Read(tenant,id);await a.Require(tenant,"studio.issue",c.UnitId);if(r.Note.Length is <3 or >2000)throw new DomainException("Explain revocation");c.Status="Revoked";c.Reason=r.Note;a.Audit(tenant,"credential.revoked",id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
  t.MapGet("/credentials/{id:guid}/file",async(Guid tenant,Guid id,string? side,string? format,AppDb db,Access a,StudioService s,IObjectStore store,StudioRenderer renderer)=>{var c=await s.Read(tenant,id);await s.Download(c);a.Audit(tenant,"credential.downloaded",id,new{side,format});await db.SaveChangesAsync();if(format=="jpg"){var snapshot=JsonSerializer.Deserialize<CredentialSnapshot>(c.Snapshot,DesignSchema.Json)!;return Results.File(renderer.Image(tenant,snapshot,side??"Front",true),"image/jpeg",c.Serial+"-"+(side??"Front")+".jpg");}Guid file=side=="Front"?c.FrontId??throw new DomainException("No front image"):side=="Back"?c.BackId??throw new DomainException("No back layout"):c.PdfId!.Value;return Results.File(store.Open(tenant,file),side==null?"application/pdf":"image/png",c.Serial+(side==null?".pdf":"-"+side+".png"));});
  t.MapPost("/credentials/{id:guid}/requests",async(Guid tenant,Guid id,CredentialRequest r,StudioService s,AppDb db,Access a)=>{var c=await s.Read(tenant,id);if(!await s.Own(tenant,c.MembershipId))throw new AccessDeniedException();if(r.Kind is not("Correction" or "Replacement" or "Lost")||r.Note.Length is <3 or >2000)throw new DomainException("Choose correction, replacement or lost and explain the request");var x=new CredentialRequest{TenantId=tenant,UnitId=c.UnitId,CredentialId=id,UserId=a.UserId,Kind=r.Kind,Note=r.Note};db.Add(x);if(r.Kind=="Lost"){c.Status="Revoked";c.Reason="Reported lost by holder";}a.Audit(tenant,"credential.holder.requested",id,new{r.Kind});await db.SaveChangesAsync();return Results.Ok(x);});
  t.MapGet("/requests",async(Guid tenant,StudioService s)=>await s.Scoped<CredentialRequest>(tenant,"studio.issue").OrderByDescending(x=>x.At).Take(100).ToListAsync());
  MapJobs(t);
  api.MapGet("/studio/fonts/{face}",(string face)=>{if(face is not("regular" or "bold"))return Results.NotFound();return Results.File(new FinanceFontResolver().GetFont(face=="bold"?"FinanceBold":"FinanceRegular"),"font/ttf");});
  api.MapGet("/credentials/verify/{token}",async(string token,AppDb db)=>{if(token.Length!=64||token.Any(c=>!Uri.IsHexDigit(c)))return Results.NotFound();var hash=CommunityService.Hash(token);var c=await db.Set<Credential>().AsNoTracking().SingleOrDefaultAsync(c=>c.TokenHash==hash);if(c==null)return Results.NotFound();var m=await db.Memberships.AsNoTracking().SingleAsync(m=>m.Id==c.MembershipId&&m.TenantId==c.TenantId);var tenant=await db.Tenants.AsNoTracking().SingleAsync(t=>t.Id==c.TenantId);var valid=c.Status=="Issued"&&c.ExpiryDate>=FinanceService.Today&&m.Status=="Active"&&m.EffectiveFrom<=DateTimeOffset.UtcNow&&(m.EndsAt==null||m.EndsAt>DateTimeOffset.UtcNow)&&tenant.Status=="Active";var policy=await db.Set<StudioPolicy>().AsNoTracking().SingleOrDefaultAsync(p=>p.TenantId==c.TenantId);var snap=JsonSerializer.Deserialize<CredentialSnapshot>(c.Snapshot,DesignSchema.Json)!;db.Audits.Add(new Audit{TenantId=c.TenantId,Action="credential.verified.public",ResourceId=c.Id,Details=JsonSerializer.Serialize(new{valid})});await db.SaveChangesAsync();return Results.Ok(new{valid,status=valid?"Valid":c.Status=="Issued"?"Expired or inactive":c.Status,displayName=policy?.PublicNames==true?snap.Fields.GetValueOrDefault("member.full_name"):null,society=tenant.Name,chapter=snap.Fields.GetValueOrDefault("chapter.name"),category=c.Category,kind=c.Kind,expiry=c.ExpiryDate});}).RequireRateLimiting("verify");
 }
 static async Task ValidateTemplate(Guid tenant,DesignTemplateWrite r,AppDb db,Access a,StudioService s){await a.Require(tenant,"studio.design",r.UnitId);if(r.UnitId!=null&&!(await s.Policy(tenant)).ChapterCustomization&&!await a.Can(tenant,"studio.settings"))throw new DomainException("Society policy does not permit local template customization");if(r.Name.Trim().Length is <2 or >160||r.Kind is not("Card" or "Certificate")||r.Category.Length is <1 or >120||r.Designation.Length>160)throw new DomainException("Enter a valid template name, kind and category");if(r.CategoryId!=null&&!await db.MembershipCategories.AnyAsync(c=>c.TenantId==tenant&&c.Id==r.CategoryId))throw new AccessDeniedException();await s.ValidateAssets(tenant,DesignSchema.Parse(r.Design));}
 internal static object Card(Credential c)=>new{c.Id,c.UnitId,c.MembershipId,c.TemplateVersionId,c.PreviousId,c.Kind,c.Category,c.Serial,status=c.Status=="Issued"&&c.ExpiryDate<FinanceService.Today?"Expired":c.Status,c.IssueDate,c.ExpiryDate,c.AuthorId,c.ApproverId,c.PdfId,c.FrontId,c.BackId,c.Reason,c.At};
 static partial void MapJobs(RouteGroupBuilder t);
}
